import{_ as e,a0 as o,w as n,s as d,ao as l,I as u,a1 as p,A as a,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"點評Linux平台上的音樂播放器Audacious 3.4 | LCTT x X-CMD","titleTemplate":false,"description":"點評Linux平台上的音樂播放器Audacious 3.4 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"點評Linux平台上的音樂播放器Audacious 3.4 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"點評Linux平台上的音樂播放器Audacious 3.4 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Audacious 3.4 for Linux Review","title":"點評Linux平台上的音樂播放器Audacious 3.4","tag":"201310","desc":""},"relativePath":"201310/Audacious 3.4 for Linux Review.md","filePath":"[post].md"}'),r={name:"201310/Audacious 3.4 for Linux Review.md"};function m(g,i,w,f,A,c){const s=o("Link");return n(),d("div",null,[i[17]||(i[17]=l(`<h1 id="點評linux平台上的音樂播放器audacious-3-4" tabindex="-1">點評Linux平台上的音樂播放器Audacious 3.4 <a class="header-anchor" href="#點評linux平台上的音樂播放器audacious-3-4" aria-label="Permalink to “點評Linux平台上的音樂播放器Audacious 3.4”">​</a></h1><p><strong>在Linux平台上，雖然音樂播放器軟件多如牛毛，但是稱得上音樂播放器這個名稱的為數不多。Audacious是一款非常知名的軟件，並且就是這些能被叫做音樂播放器的少數軟件之一。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-2.jpg" alt=""></p><p>###版本點評：Audacious 3.4</p><p>Audacious是一款開源的音樂播放器軟件。 作為XMMS播放器軟件的分支，Audacious播放器可以隨心所欲的播放你的音樂，並且不會搶佔其他任務的系統資源。 在你的所有音樂庫裏，你可以進行拖動文件夾和放置私人的歌曲文件、搜索歌手和專輯或者編輯你的自定義播放列表等操作。</p><p><strong>特性:</strong></p><ul><li>聆聽CD</li><li>簡潔的播放列表</li><li>清爽的界面</li><li>輕量級的系統資源利用</li><li>多種音效設置</li><li>大量的plugins</li></ul><p>在Linux平台上並不缺乏音樂播放器軟件，但每過去一年，這種類型的軟件定義變得越來越模糊。開發商正在實驗新的東西，他們嘗試着模仿其他平台的軟件以及從其他平台複製有特色的功能過來。</p><p>今天在用的大多數播放器，至少是一些主要的發佈版本，已經嘗試着加入一些功能，並不僅僅是一個簡單的媒體播放器。開發商已經實現了在線電台、廣播，甚至在界面上就可以直接購買音樂的功能。</p><p>雖然這種創新是值得提倡的，但在音頻播放器上做的太過火了。開發商已經忘記了這軟件的主要作用。雖然不用打開網絡瀏覽器就能購買音樂很不錯，但是一款音頻播放軟件不應該把此功能當作核心。</p><p>我們現在看看Audacious，一款在Linux平台上的“老校友”式的音頻播放軟件，仍在更新及增加新血液，它不會為了要得到所有第三方服務而改變核心功能。</p><p>###安裝</p><p>有複雜的和簡單的兩種方式來安裝Audacious。複雜的方式即從源代碼開始編譯安裝，其實沒有必要這樣做。如果選擇從源代碼編譯開始，那麼以後的更新都要用相同的方法來做，這將是非常繁瑣的過程。</p><p>我們已經在Ubuntu 13.10 (Saucy Salamander)系統上安裝了Audacious 3.4。雖然Ubuntu 13.10系統仍然處於測試階段，但是除了一個異常外它已經被證實是一個穩定的操作系統。</p><p>這個軟件的最新版本是在官方源已經可用，可以通過Ubuntu軟件中心安裝或使用終端來安裝。通常，我們建議用後一種方式，因為Ubuntu軟件中心需要一些依賴的軟件登錄，即使它們是免費的，而且最好看看在安裝過程中具體的發生了什麼。</p><p>打開終端，輸入如下的命令：</p><pre><code>sudo apt-get install audacious
</code></pre><p>當所有的包都已安裝結束，像平時一樣，打開Unity Dash，鍵入應用程序的名稱，你就能找到這個播放器的快捷圖標。</p><p>###總結</p><p>如果您正在尋找傳統但也包含了一些新的功能的音頻播放器，你應該試試Audacious。</p><p>該軟件有一個簡單的界面，它幾乎不佔用任何系統資源，沒有任何花裏胡哨的功能，這也正是它的風格。Audacious播放音樂，就這樣，一點也不突兀。</p><p><strong>優點</strong></p><p>我最喜歡Audacious的就是它清爽乾淨，而不是偽裝簡單的界面。從一開始，你會發現，一切都已經設計了這樣一種方式，你幾乎不可能會犯任何錯誤。</p><p>不像它的一些競爭對手軟件（對，我説的就是Rythmbox），為了導入一個簡單的文件夾，你將四處摸索此功能所在何處。它不會用各樣的排序你的音樂庫的方式來打擾用户，顯示歌曲信息的方式也很舒服。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-4.jpg" alt=""></p><p>它還配備了一個非常簡單和高效的懸停界面，當你想看到一首歌的細節，但你不想點擊該特定項目，這是非常有用的。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-3.jpg" alt=""></p><p>Audacious還配備了三個不同的可以使老用户回到以前所用的“真正的”音頻播放器的可視化模型，並且所有的都可以修改和定製。</p><p>所有你期望一個媒體播放器所具有的其他選項，它都具有，談論他們不是主要目的。您可以導入播放列表，設置重複播放，甚至還有一個非常簡單和良好的均衡器。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-10.jpg" alt=""></p><p>Audacious的優勢之一是默認包括的音效，如去除人聲，採樣率轉換器，通道混合器，速度和間距，以及更多。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-6.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-5.jpg" alt=""></p><p>從偏好設置裏，大量的插件也可以被激活，如：專輯封面，歌詞，狀態圖標，GNOME快捷鍵以及其它的一些等等。請注意，所有這些插件在默認情況下是禁用的，他們得由用户手工開啓，以便使界面乾淨漂亮。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-7.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-8.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Audacious-Review-387093-9.jpg" alt=""></p><p><strong>不足</strong></p><p>關於此軟件的評論，我可能會有點主觀，因為我真的不能忍受過於複雜的音頻播放器，Audacious正對我的胃口。但是，説句公道話，我曾經是愛過能夠添加排序字段的播放列表功能的。</p><p>這款應用還具備第二個“Winamp”模式的特性，這使它看起來像Windows平台上的Winamp播放器，不幸的是，每次我試着激它的時候Audacious崩潰了，但也可能是因為Ubuntu13.10目前還不穩定。</p><p><strong>Audacious 3.4.1: 免費下載</strong></p>`,41)),u("ul",null,[u("li",null,[p(s,{href:"http://distfiles.audacious-media-player.org/audacious-3.4.1.tar.bz2"},{default:a(()=>[...i[0]||(i[0]=[t("Audacious 3.4.1 tar.bz2",-1)])]),_:1}),i[1]||(i[1]=t("[sources] [464 KB]",-1))]),u("li",null,[p(s,{href:"http://audacious-media-player.org/download"},{default:a(()=>[...i[2]||(i[2]=[t("Ubuntu 12.10 (Repository)",-1)])]),_:1}),i[3]||(i[3]=t("[ubuntu_deb] [0 KB]",-1))]),u("li",null,[p(s,{href:"http://audacious-media-player.org/download"},{default:a(()=>[...i[4]||(i[4]=[t("Red Hat/Fedora/Mandriva/openSUSE RPM (Repository)",-1)])]),_:1}),i[5]||(i[5]=t("[rh_rpm] [0 KB]",-1))])]),i[18]||(i[18]=u("hr",null,null,-1)),u("p",null,[i[7]||(i[7]=t("via: ",-1)),p(s,{href:"http://www.softpedia.com/reviews/linux/Audacious-Review-387093.shtml"},{default:a(()=>[...i[6]||(i[6]=[t("http://www.softpedia.com/reviews/linux/Audacious-Review-387093.shtml",-1)])]),_:1})]),u("p",null,[i[10]||(i[10]=t("本文由 ",-1)),p(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[8]||(i[8]=[t("LCTT",-1)])]),_:1}),i[11]||(i[11]=t(" 原創翻譯，",-1)),p(s,{href:"http://linux.cn/"},{default:a(()=>[...i[9]||(i[9]=[t("Linux中國",-1)])]),_:1}),i[12]||(i[12]=t(" 榮譽推出",-1))]),u("p",null,[i[15]||(i[15]=t("譯者：",-1)),p(s,{href:"https://github.com/runningwater"},{default:a(()=>[...i[13]||(i[13]=[t("runningwater",-1)])]),_:1}),i[16]||(i[16]=t(" 校對：",-1)),p(s,{href:"https://linux.cn/space/wxy"},{default:a(()=>[...i[14]||(i[14]=[t("wxy",-1)])]),_:1})])])}const v=e(r,[["render",m]]);export{T as __pageData,v as default};
